import{d as g,C as n,o as s,c as h,E as a,a3 as i}from"./chunks/framework.D4-ViStF.js";const c=JSON.parse('{"title":"观卦","description":"第二十卦·风地观——风行地上，省方观民设教。","frontmatter":{"title":"观卦","description":"第二十卦·风地观——风行地上，省方观民设教。","category":"hexagram","aliases":["观","风地观"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-20.md","filePath":"yijing/hexagrams/hexagram-20.md","lastUpdated":1787730063000}'),u={name:"yijing/hexagrams/hexagram-20.md"},x=g({...u,setup(p){const r=[{id:"tongguan",term:"童观",pinyin:"tóng guān",meaning:"孩童式的观看，懵懂、认知有限。认知决定角度，角度决定所见。"},{id:"kuiguan",term:"窥观",pinyin:"kuī guān",meaning:"从缝隙中看，开始接触认知之外的事物。不是全貌，但已突破童观的封闭。"},{id:"guanwosheng",term:"观我生",pinyin:"guān wǒ shēng",meaning:"观察自己的生——自己的认知与行为。六三与九五同辞，境界不同。"},{id:"guanguozhiguang",term:"观国之光",pinyin:"guān guó zhī guāng",meaning:"观察国家的光彩，看见文明、趋势与更大的格局。"},{id:"liyongbin",term:"利用宾于王",pinyin:"lì yòng bīn yú wáng",meaning:"以宾客之礼、不卑不亢地走向那道光。不是去争、去证明，是有备而来。"},{id:"guanqisheng",term:"观其生",pinyin:"guān qí shēng",meaning:"观生命本身。「其」字囊括一切，连观察者本身也被观察了。"},{id:"xiaorendao",term:"小人道",pinyin:"xiǎo rén dào",meaning:"小人之道。童观是小人的常态，认知未开。"},{id:"yikechou",term:"亦可丑",pinyin:"yì kě chǒu",meaning:"也是可羞的。窥观而守正，对女子尚可，但终究不是观的正道。"},{id:"weishidao",term:"未失道",pinyin:"wèi shī dào",meaning:"没有失去正道。进退未定，但尚未偏离道。"},{id:"shangbin",term:"尚宾",pinyin:"shàng bīn",meaning:"崇尚宾客之礼。观国之光，尚宾也。"},{id:"guanmin",term:"观民",pinyin:"guān mín",meaning:"观察民情。观我生，就是观民——反观自己，也就照见了众人。"},{id:"zhiweiping",term:"志未平",pinyin:"zhì wèi píng",meaning:"志向尚未平定。观其生，志未平也——「观」没有尽头，永远在路上。"}],e=[{position:"初六",type:"yin",text:"童观，小人无咎，君子吝。",xiang:"初六童观，小人道也。",textModern:"孩童式的观看，懵懂、认知有限；认知决定角度，角度决定所见。对小人无咎（认知本就如此），对君子则是不足。",xiangModern:"童观是小人之道——停留在懵懂的观看，是认知未开的状态。"},{position:"六二",type:"yin",text:"窥观，利女贞。",xiang:"窥观女贞，亦可丑也。",textModern:"从缝隙中看，开始接触认知之外的事物；不是全貌，但已突破童观的封闭。以柔顺、守正的姿态持续观察。",xiangModern:"从缝隙窥看而守正，对女子尚且可以，但终究是可羞的——不是观的正道。"},{position:"六三",type:"yin",text:"观我生，进退。",xiang:"观我生进退，未失道也。",textModern:"第一次「观我生」——新旧认知碰撞，可以退回去，也可以接受新的；进退未定，是真实的摇摆，打破固有认知的关口就在这里。",xiangModern:"观我生而进退，尚未失去正道——摇摆本身不可怕，只要不偏离道。"},{position:"六四",type:"yin",text:"观国之光，利用宾于王。",xiang:"观国之光，尚宾也。",textModern:"因为自己不同了，开始以新认知观察自身以外的事物；国之光浮现——看见了文明、趋势、更大的格局。以宾客之礼、不卑不亢地走向那道光。",xiangModern:"观国之光，在于崇尚宾客之礼——不是去争、去证明，是有备而来。"},{position:"九五",type:"yang",text:"观我生，君子无咎。",xiang:"观我生，观民也。",textModern:"第二次「观我生」，与六三同辞，境界全然不同——六三摇摆，九五有定力、观而不乱。君子之位，持续自观，不因外境动摇，走完了一生（不是长度，是完整度）。",xiangModern:"观我生，就是观民——反观自己，也就照见了众人。"},{position:"上九",type:"yang",text:"观其生，君子无咎。",xiang:"观其生，志未平也。",textModern:"一字之差，观我生 → 观其生。不再是「看意义上的我」，而是放下自我、观生命本身——英雄、小人、市井、圣贤，全在「其」中，连观察者本身也被观察了。",xiangModern:"观其生，而志向尚未平定——因为「观」没有尽头，永远在路上。"}];return(m,t)=>{const o=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),d=n("DaoKeywordCards");return s(),h("div",null,[a(o,{name:"观",fullName:"风地观",upper:"☴",lower:"☷",guaCi:"观，盥而不荐，有孚颙若。",pinyin:["guān"],element:"木",direction:"东南",insight:"风行地上，遍观万物；盥而不荐，有孚颙若，观在每一刻的诚实。",guaSlug:"20fengdiguan",lines:e}),t[0]||(t[0]=i("",9)),a(l,{element:"木",guaSlug:"20fengdiguan",glossary:r,items:e}),t[1]||(t[1]=i("",24)),a(d,{title:"字词释义",items:[{term:"观",pinyin:["guān"],meaning:"观看、观察。风行地上，遍观万物。"},{term:"盥",pinyin:["guàn"],meaning:"祭祀前的洗手净心。"},{term:"荐",pinyin:["jiàn"],meaning:"正式献祭。「盥而不荐」：状态在献祭之前就已经在了。"},{term:"颙若",pinyin:["yóng","ruò"],meaning:"严肃凝重的样子。"},{term:"童观",pinyin:["tóng","guān"],meaning:"孩童式的观看，懵懂、认知有限。"},{term:"窥观",pinyin:["kuī","guān"],meaning:"从缝隙中看，接触认知之外。"},{term:"观我生",pinyin:["guān","wǒ","shēng"],meaning:"观察自己的生——认知与行为。"},{term:"观国之光",pinyin:["guān","guó","zhī","guāng"],meaning:"观察国家的光彩、文明与格局。"},{term:"观其生",pinyin:["guān","qí","shēng"],meaning:"观生命本身，连观察者也被观察。"},{term:"宾于王",pinyin:["bīn","yú","wáng"],meaning:"以宾客之礼事王，不卑不亢。"}]}),t[2]||(t[2]=i("",21))])}}});export{c as __pageData,x as default};
